// Character classification and scanning primitives.
//
// This project deliberately contains no pattern-matching engine: every construct is
// recognised by advancing a cursor over the source. These helpers are the vocabulary
// the block and inline recognisers are written in.
import { WORD_DATA, SPACE_DATA } from './unicodedata.mjs';

function decode(data) {
  const starts = [];
  const ends = [];
  let prev = 0;
  for (const part of data.split(',')) {
    const dot = part.indexOf('.');
    const start = prev + parseInt(part.slice(0, dot), 36);
    const end = start + parseInt(part.slice(dot + 1), 36);
    starts.push(start);
    ends.push(end);
    prev = end;
  }
  return { starts, ends };
}

const WORD = decode(WORD_DATA);
const SPACE = decode(SPACE_DATA);

function inSet(set, cp) {
  const { starts, ends } = set;
  let lo = 0;
  let hi = starts.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (cp < starts[mid]) hi = mid - 1;
    else if (cp > ends[mid]) lo = mid + 1;
    else return true;
  }
  return false;
}

// Fast path for ASCII, table lookup above it.
const ASCII_WORD = new Uint8Array(128);
for (let c = 0; c < 128; c++) {
  ASCII_WORD[c] = (c === 95 || (c >= 48 && c <= 57) || (c >= 65 && c <= 90) || (c >= 97 && c <= 122)) ? 1 : 0;
}

export function isWordCodePoint(cp) {
  if (cp < 128) return ASCII_WORD[cp] === 1;
  return inSet(WORD, cp);
}

export function isSpaceCodePoint(cp) {
  if (cp === 32 || (cp >= 9 && cp <= 13)) return true;
  if (cp < 128) return false;
  return inSet(SPACE, cp);
}

// Word/space tests that look at the character *at* an index, decoding surrogate
// pairs so astral letters classify the same way Python would see them.
export function isWordAt(s, i) {
  if (i < 0 || i >= s.length) return false;
  const code = s.charCodeAt(i);
  if (code >= 0xd800 && code <= 0xdbff && i + 1 < s.length) {
    const next = s.charCodeAt(i + 1);
    if (next >= 0xdc00 && next <= 0xdfff) return isWordCodePoint(s.codePointAt(i));
  }
  if (code >= 0xdc00 && code <= 0xdfff && i > 0) {
    const prev = s.charCodeAt(i - 1);
    if (prev >= 0xd800 && prev <= 0xdbff) return isWordCodePoint(s.codePointAt(i - 1));
  }
  return isWordCodePoint(code);
}

export function isWordChar(ch) {
  return ch ? isWordCodePoint(ch.codePointAt(0)) : false;
}

export function isSpaceChar(ch) {
  return ch ? isSpaceCodePoint(ch.charCodeAt(0)) : false;
}

export function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

export function isAsciiAlpha(ch) {
  return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z');
}

export function isAsciiAlnum(ch) {
  return isDigit(ch) || isAsciiAlpha(ch);
}

/** True when position `i` sits on a `\b` boundary of the Python flavour. */
export function isWordBoundary(s, i) {
  return isWordAt(s, i - 1) !== isWordAt(s, i);
}

/** Index of the first character that is not `ch`, starting at `from`. */
export function skipChar(s, from, ch) {
  let i = from;
  while (i < s.length && s[i] === ch) i++;
  return i;
}

/** Index of the first non-(space|tab) character, starting at `from`. */
export function skipBlank(s, from) {
  let i = from;
  while (i < s.length && (s[i] === ' ' || s[i] === '\t')) i++;
  return i;
}

/** Index of the first non-Python-whitespace character, starting at `from`. */
export function skipSpace(s, from) {
  let i = from;
  while (i < s.length && isSpaceCodePoint(s.charCodeAt(i))) i++;
  return i;
}

/** Count of leading spaces (tabs not expanded). */
export function leadingSpaces(s) {
  return skipChar(s, 0, ' ');
}

/** True when the string holds nothing but Python whitespace. */
export function isBlankLine(s) {
  return skipSpace(s, 0) === s.length;
}

/** Python's str.rstrip() with no argument. */
export function rstrip(s) {
  let end = s.length;
  while (end > 0 && isSpaceCodePoint(s.charCodeAt(end - 1))) end--;
  return s.slice(0, end);
}

/** Python's str.lstrip() with no argument. */
export function lstrip(s) {
  return s.slice(skipSpace(s, 0));
}

export function strip(s) {
  return rstrip(lstrip(s));
}

/** Python's str.rstrip(chars) / lstrip(chars) / strip(chars). */
export function rstripChars(s, chars) {
  let end = s.length;
  while (end > 0 && chars.indexOf(s[end - 1]) !== -1) end--;
  return s.slice(0, end);
}

export function lstripChars(s, chars) {
  let i = 0;
  while (i < s.length && chars.indexOf(s[i]) !== -1) i++;
  return s.slice(i);
}

export function stripChars(s, chars) {
  return rstripChars(lstripChars(s, chars), chars);
}

/** Split on a literal separator, like Python's str.split(sep). */
export function splitLiteral(s, sep) {
  const out = [];
  let from = 0;
  for (;;) {
    const at = s.indexOf(sep, from);
    if (at === -1) break;
    out.push(s.slice(from, at));
    from = at + sep.length;
  }
  out.push(s.slice(from));
  return out;
}

/** Replace every literal occurrence of `find` with `repl`. */
export function replaceAll(s, find, repl) {
  if (find === '') return s;
  return splitLiteral(s, find).join(repl);
}

/** True when every character of `s` from `from` to `to` is `ch`. */
export function allChar(s, ch, from = 0, to = s.length) {
  if (to <= from) return false;
  for (let i = from; i < to; i++) if (s[i] !== ch) return false;
  return true;
}

/** Number of consecutive `ch` starting at `from`. */
export function runLength(s, from, ch) {
  let n = 0;
  while (from + n < s.length && s[from + n] === ch) n++;
  return n;
}

/** Python's str.lower() is locale-independent; JS toLowerCase is close enough for ASCII tags. */
export function lower(s) {
  return s.toLowerCase();
}

