// HTML serializer. Mirrors the ElementTree-derived serializer Python-Markdown ships:
// attributes are emitted in sorted order, void elements close with " />" in the
// default xhtml output format, and <script>/<style> text is not escaped.
import { Comment, ProcessingInstruction, Element } from './etree.mjs';
import { replaceAll } from './scan.mjs';

export const HTML_EMPTY = new Set([
  'area', 'base', 'basefont', 'br', 'col', 'embed', 'frame', 'hr', 'img',
  'input', 'isindex', 'link', 'meta', 'param', 'source', 'track', 'wbr',
]);

const RAW_TEXT = new Set(['script', 'style']);

function escapeCdata(text) {
  let out = text;
  if (out.indexOf('&') !== -1) out = replaceAll(out, '&', '&amp;');
  if (out.indexOf('<') !== -1) out = replaceAll(out, '<', '&lt;');
  if (out.indexOf('>') !== -1) out = replaceAll(out, '>', '&gt;');
  return out;
}

function escapeAttrib(text) {
  let out = text;
  if (out.indexOf('&') !== -1) out = replaceAll(out, '&', '&amp;');
  if (out.indexOf('<') !== -1) out = replaceAll(out, '<', '&lt;');
  if (out.indexOf('>') !== -1) out = replaceAll(out, '>', '&gt;');
  if (out.indexOf('"') !== -1) out = replaceAll(out, '"', '&quot;');
  if (out.indexOf('\n') !== -1) out = replaceAll(out, '\n', '&#10;');
  return out;
}

/** Python compares strings by code point; JS sorts by UTF-16 unit. Normalise that. */
function codePointCompare(a, b) {
  const ai = [...a];
  const bi = [...b];
  const n = Math.min(ai.length, bi.length);
  for (let i = 0; i < n; i++) {
    const x = ai[i].codePointAt(0);
    const y = bi[i].codePointAt(0);
    if (x !== y) return x < y ? -1 : 1;
  }
  return ai.length === bi.length ? 0 : (ai.length < bi.length ? -1 : 1);
}

function sortedItems(el) {
  const items = el.items();
  items.sort((p, q) => codePointCompare(p[0], q[0]) || codePointCompare(String(p[1]), String(q[1])));
  return items;
}

function serialize(out, node, format) {
  if (typeof node === 'string') {
    out.push(escapeCdata(node));
    return;
  }
  const tag = node.tag;
  const text = node.text;

  if (tag === Comment) {
    out.push('<!--' + escapeCdata(text === null ? '' : text) + '-->');
  } else if (tag === ProcessingInstruction) {
    out.push('<?' + escapeCdata(text === null ? '' : text) + '?>');
  } else if (tag === null) {
    // A bare container: emit its contents only.
    if (text) out.push(escapeCdata(text));
    for (const child of node.children) serialize(out, child, format);
  } else {
    out.push('<' + tag);
    for (const [k, v] of sortedItems(node)) {
      out.push(' ' + k + '="' + escapeAttrib(v === null || v === undefined ? '' : String(v)) + '"');
    }
    const lowered = tag.toLowerCase();
    if (text !== null || node.children.length || !HTML_EMPTY.has(lowered)) {
      out.push('>');
      if (text) out.push(RAW_TEXT.has(lowered) ? text : escapeCdata(text));
      for (const child of node.children) serialize(out, child, format);
      out.push('</' + tag + '>');
    } else if (format === 'xhtml') {
      out.push(' />');
    } else {
      out.push('>');
    }
  }
  if (node.tail) out.push(escapeCdata(node.tail));
}

