 * Serializes an element. The document root itself is not emitted — only its
 * children — which is how `markdown.markdown()` produces a bare HTML fragment.
 */
export function toHtmlString(element, format = 'xhtml') {
  const out = [];
  serialize(out, element, format);
  return out.join('');
}

export function serializeChildren(element, format = 'xhtml') {
  const out = [];
  if (element.text) out.push(escapeCdata(element.text));
  for (const child of element.children) serialize(out, child, format);
  return out.join('');
}

export { escapeCdata, escapeAttrib };

