// Shared constants, the ordered processor registry, and the raw-HTML stash.

/** Placeholder sentinels. These are the same control-character markers the
 *  reference implementation embeds in the text while it works, chosen so they
 *  cannot collide with anything a document legitimately contains. */
export const STX = '';
export const ETX = '';
export const INLINE_PLACEHOLDER_PREFIX = STX + 'klzzwxh:';
export const AMP_SUBSTITUTE = STX + 'amp' + ETX;
export const HTML_PLACEHOLDER_PREFIX = STX + 'wzxhzdk:';
export const TAG_PLACEHOLDER_PREFIX = STX + 'hzzhzkh:';

export function inlinePlaceholder(index) {
  return INLINE_PLACEHOLDER_PREFIX + index + ETX;
}

export function htmlPlaceholder(index) {
  return HTML_PLACEHOLDER_PREFIX + index + ETX;
}

export function tagPlaceholder(index) {
  return TAG_PLACEHOLDER_PREFIX + index + ETX;
}

export const BLOCK_LEVEL_ELEMENTS = [
  // Elements that must never be wrapped in a paragraph.
  'address', 'article', 'aside', 'blockquote', 'details', 'div', 'dl',
  'fieldset', 'figcaption', 'figure', 'footer', 'form', 'h1', 'h2', 'h3',
  'h4', 'h5', 'h6', 'header', 'hgroup', 'hr', 'main', 'menu', 'nav', 'ol',
  'p', 'pre', 'section', 'table', 'ul',
  // Elements whose contents markdown should leave structurally alone.
  'canvas', 'colgroup', 'dd', 'body', 'dt', 'group', 'iframe', 'li', 'legend',
  'math', 'map', 'noscript', 'output', 'object', 'option', 'progress', 'script',
  'style', 'summary', 'tbody', 'td', 'textarea', 'tfoot', 'th', 'thead', 'tr',
  'video',
];

/** The escaping applied to the contents of code blocks and code spans. */
export function codeEscape(text) {
  let out = text;
  if (out.indexOf('&') !== -1) out = out.split('&').join('&amp;');
  if (out.indexOf('<') !== -1) out = out.split('<').join('&lt;');
  if (out.indexOf('>') !== -1) out = out.split('>').join('&gt;');
  return out;
}

/**
 * An ordered collection keyed by name and sorted by descending priority.
 * Registration order breaks ties, so equal priorities keep insertion order.
 */
export class Registry {
  constructor() {
    this._data = new Map();
    this._priority = [];
    this._sorted = null;
  }

  register(item, name, priority) {
    if (this._data.has(name)) this.deregister(name);
    this._data.set(name, item);
    this._priority.push({ name, priority });
    this._sorted = null;
    return this;
  }

  deregister(name, strict = true) {
    if (!this._data.has(name)) {
      if (strict) throw new Error('No item named "' + name + '" exists.');
      return this;
    }
    this._data.delete(name);
    this._priority = this._priority.filter((p) => p.name !== name);
    this._sorted = null;
    return this;
  }

  has(name) {
    return this._data.has(name);
  }

  get(name) {
    return this._data.get(name);
  }

  /** Items in execution order: highest priority first. */
  values() {
    if (this._sorted === null) {
      const indexed = this._priority.map((p, i) => ({ ...p, i }));
      indexed.sort((a, b) => (b.priority - a.priority) || (a.i - b.i));
      this._sorted = indexed.map((p) => this._data.get(p.name));
    }
    return this._sorted;
  }

  names() {
    if (this._sorted === null) this.values();
    const indexed = this._priority.map((p, i) => ({ ...p, i }));
    indexed.sort((a, b) => (b.priority - a.priority) || (a.i - b.i));
    return indexed.map((p) => p.name);
  }

  [Symbol.iterator]() {
    return this.values()[Symbol.iterator]();
  }
}

/**
 * Holds raw HTML pulled out of the document. The text carries a placeholder in
 * its place until a postprocessor swaps the original markup back in.
 */
export class HtmlStash {
  constructor() {
    this.htmlCounter = 0;
    this.rawHtmlBlocks = [];
    this.tagCounter = 0;
    this.tagData = [];
  }

  store(html) {
    this.rawHtmlBlocks.push(html);
    const placeholder = htmlPlaceholder(this.htmlCounter);
    this.htmlCounter += 1;
    return placeholder;
  }

  reset() {
    this.htmlCounter = 0;
    this.rawHtmlBlocks = [];
  }

  storeTag(tag, attrs, leftIndex, rightIndex) {
    this.tagData.push({ tag, attrs, leftIndex, rightIndex });
    this.tagCounter += 1;
    return tagPlaceholder(this.tagCounter - 1);
  }
}

/** Python's `str.expandtabs(tabsize)` — column-aware, not a blind replace. */
export function expandTabs(s, tabsize = 4) {
  if (s.indexOf('\t') === -1) return s;
  let out = '';
  let col = 0;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (ch === '\t') {
      if (tabsize > 0) {
        const width = tabsize - (col % tabsize);
        out += ' '.repeat(width);
        col += width;
      }
    } else if (ch === '\n' || ch === '\r') {
      out += ch;
      col = 0;
    } else {
      out += ch;
      col += 1;
    }
  }
  return out;
}

