    const dot = part.indexOf('.');
    const start = prev + parseInt(part.slice(0, dot), 36);
    const end = start + parseInt(part.slice(dot + 1), 36);
    starts.push(start);
    ends.push(end);
    prev = end;
  }
  return { starts, ends };
}

const WORD = decode(WORD_DATA);
const SPACE = decode(SPACE_DATA);

function inSet(set, cp) {
  const { starts, ends } = set;
  let lo = 0;
  let hi = starts.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (cp < starts[mid]) hi = mid - 1;
    else if (cp > ends[mid]) lo = mid + 1;
    else return true;
  }
  return false;
}

// Fast path for ASCII, table lookup above it.
