  return s.slice(skipSpace(s, 0));
}

export function strip(s) {
  return rstrip(lstrip(s));
}

/** Python's str.rstrip(chars) / lstrip(chars) / strip(chars). */
export function rstripChars(s, chars) {
  let end = s.length;
  while (end > 0 && chars.indexOf(s[end - 1]) !== -1) end--;
