// first registered processor that claims it.
import { Element } from './etree.mjs';
import { Registry } from './util.mjs';

/** A stack of parser modes ("list", "looselist", "blockquote", "detabbed", ...). */
export class State {
  constructor() {
    this.stack = [];
  }

  set(state) {
    this.stack.push(state);
  }

  reset() {
    this.stack.pop();
  }

  isstate(state) {
    return this.stack.length > 0 && this.stack[this.stack.length - 1] === state;
  }
}

export class BlockParser {
  constructor(md) {
    this.blockprocessors = new Registry();
    this.state = new State();
    this.md = md;
  }

  parseDocument(lines) {
    this.root = new Element(this.md.docTag);
    this.parseChunk(this.root, lines.join('\n'));
    return this.root;
  }

  /** Splits on blank lines, then parses each resulting block. */
  parseChunk(parent, text) {
    this.parseBlocks(parent, text.split('\n\n'));
  }

  parseBlocks(parent, blocks) {
    while (blocks.length) {
      let handled = false;
      for (const processor of this.blockprocessors.values()) {
        if (processor.test(parent, blocks[0])) {
