// The core block processors, in registration order:
//   empty 100, indent 90, code 80, hashheader 70, setextheader 60, hr 50,
//   olist 40, ulist 30, quote 20, reference 15, paragraph 10
import { Element, SubElement } from './etree.mjs';
import { codeEscape } from './util.mjs';
import { strip, lstrip, rstrip, rstripChars, lstripChars, skipChar } from './scan.mjs';
import {
  searchHashHeader, matchSetextHeader, searchHR, searchBlockQuote, cleanQuoteLine,
  matchListItem, matchIndentedListItem, leadingInteger, indentLevel, searchReference,
} from './matchers.mjs';

export class BlockProcessor {
  constructor(parser) {
    this.parser = parser;
    this.tabLength = parser.md.tabLength;
  }

  lastChild(parent) {
    return parent.length ? parent.child(-1) : null;
  }

  /**
   * Removes one indent unit from the front of each line, stopping at the first
   * line that is neither indented nor blank. Returns [detabbed, remainder].
   */
  detab(text, length = null) {
    const width = length === null ? this.tabLength : length;
    const pad = ' '.repeat(width);
    const lines = text.split('\n');
    const kept = [];
    for (const line of lines) {
      if (line.startsWith(pad)) kept.push(line.slice(width));
      else if (!strip(line)) kept.push('');
      else break;
    }
    return [kept.join('\n'), lines.slice(kept.length).join('\n')];
  }

  /** Removes `level` indent units from every line that has them. */
  looseDetab(text, level = 1) {
    const pad = ' '.repeat(this.tabLength * level);
    return text.split('\n')
      .map((line) => (line.startsWith(pad) ? line.slice(this.tabLength * level) : line))
      .join('\n');
  }

  test() {
    return false;
  }

  run() {
    return false;
  }
}

export class EmptyBlockProcessor extends BlockProcessor {
  test(parent, block) {
    return !block || block.startsWith('\n');
  }

  run(parent, blocks) {
    const block = blocks.shift();
    let filler = '\n\n';
    if (block) {
      filler = '\n';
      const theRest = block.slice(1);
      if (theRest) blocks.unshift(theRest);
    }
    const sibling = this.lastChild(parent);
    if (sibling !== null && sibling.tag === 'pre' && sibling.length && sibling.child(0).tag === 'code') {
      // Blank lines inside a code block are preserved rather than ending it.
      sibling.child(0).text = (sibling.child(0).text || '') + filler;
      sibling.child(0).atomicText = true;
    }
    return undefined;
  }
}

export class ListIndentProcessor extends BlockProcessor {
  constructor(parser) {
    super(parser);
    this.ITEM_TYPES = ['li'];
    this.LIST_TYPES = ['ul', 'ol'];
  }

  test(parent, block) {
    return block.startsWith(' '.repeat(this.tabLength))
      && !this.parser.state.isstate('detabbed')
      && (this.ITEM_TYPES.indexOf(parent.tag) !== -1
        || (parent.length && parent.child(-1) !== null && this.LIST_TYPES.indexOf(parent.child(-1).tag) !== -1));
  }

  run(parent, blocks) {
    let block = blocks.shift();
    const { level, sibling } = this.getLevel(parent, block);
    block = this.looseDetab(block, level);
    this.parser.state.set('detabbed');
    if (this.ITEM_TYPES.indexOf(parent.tag) !== -1) {
      if (parent.length && this.LIST_TYPES.indexOf(parent.child(-1).tag) !== -1) {
        this.parser.parseBlocks(parent.child(-1), [block]);
      } else {
        this.parser.parseBlocks(parent, [block]);
      }
    } else if (this.ITEM_TYPES.indexOf(sibling.tag) !== -1) {
      this.parser.parseBlocks(sibling, [block]);
    } else if (sibling.length && this.ITEM_TYPES.indexOf(sibling.child(-1).tag) !== -1) {
      const li = sibling.child(-1);
      if (li.text) {
        // Existing item text has to become a paragraph before more blocks join it.
        const p = new Element('p');
        p.text = li.text;
        p.atomicText = li.atomicText;
        li.text = '';
        li.atomicText = false;
        li.insert(0, p);
      }
      this.parser.parseChunk(li, block);
    } else {
      this.createItem(sibling, block);
    }
    this.parser.state.reset();
    return undefined;
  }

  createItem(parent, block) {
    const li = SubElement(parent, 'li');
    this.parser.parseBlocks(li, [block]);
  }

  getLevel(parent, block) {
    const indent = indentLevel(block, this.tabLength);
    let level = this.parser.state.isstate('list') ? 1 : 0;
    let current = parent;
    while (indent > level) {
      const child = this.lastChild(current);
      if (child !== null && (this.LIST_TYPES.indexOf(child.tag) !== -1 || this.ITEM_TYPES.indexOf(child.tag) !== -1)) {
        if (this.LIST_TYPES.indexOf(child.tag) !== -1) level += 1;
        current = child;
      } else {
        break;
      }
    }
    return { level, sibling: current };
  }
}

export class CodeBlockProcessor extends BlockProcessor {
  test(parent, block) {
    return block.startsWith(' '.repeat(this.tabLength));
  }

  run(parent, blocks) {
    const sibling = this.lastChild(parent);
    let block = blocks.shift();
    let theRest = '';
    if (sibling !== null && sibling.tag === 'pre' && sibling.length && sibling.child(0).tag === 'code') {
      // Continuation of the previous code block across a blank line.
      const code = sibling.child(0);
      [block, theRest] = this.detab(block);
      code.text = (code.text || '') + '\n' + codeEscape(rstrip(block)) + '\n';
      code.atomicText = true;
    } else {
      const pre = SubElement(parent, 'pre');
      const code = SubElement(pre, 'code');
      [block, theRest] = this.detab(block);
      code.text = codeEscape(rstrip(block)) + '\n';
      code.atomicText = true;
    }
    if (theRest) blocks.unshift(theRest);
    return undefined;
  }
}

export class BlockQuoteProcessor extends BlockProcessor {
  test(parent, block) {
    return searchBlockQuote(block) !== null;
  }

  run(parent, blocks) {
    let block = blocks.shift();
    const m = searchBlockQuote(block);
    if (m) {
      const before = block.slice(0, m.start);
      this.parser.parseBlocks(parent, [before]);
      block = block.slice(m.start).split('\n').map(cleanQuoteLine).join('\n');
    }
    const sibling = this.lastChild(parent);
    const quote = (sibling !== null && sibling.tag === 'blockquote') ? sibling : SubElement(parent, 'blockquote');
    this.parser.state.set('blockquote');
    this.parser.parseChunk(quote, block);
    this.parser.state.reset();
    return undefined;
  }
}

export class OListProcessor extends BlockProcessor {
  constructor(parser) {
    super(parser);
    this.TAG = 'ol';
    this.KIND = 'ol';
    this.STARTSWITH = '1';
    this.LAZY_OL = true;
    this.SIBLING_TAGS = ['ol', 'ul'];
  }

  test(parent, block) {
    return matchListItem(block, this.KIND) !== null;
  }

  run(parent, blocks) {
    const items = this.getItems(blocks.shift());
    const sibling = this.lastChild(parent);
    let lst;
    if (sibling !== null && this.SIBLING_TAGS.indexOf(sibling.tag) !== -1) {
      lst = sibling;
      const last = lst.child(-1);
      if (last.text) {
        const p = new Element('p');
        p.text = last.text;
        p.atomicText = last.atomicText;
        last.text = '';
        last.atomicText = false;
        last.insert(0, p);
      }
      const lch = this.lastChild(last);
      if (lch !== null && lch.tail) {
        const p = SubElement(last, 'p');
        p.text = lstrip(lch.tail);
        lch.tail = '';
      }
      const li = SubElement(lst, 'li');
      this.parser.state.set('looselist');
      const firstitem = items.shift();
      this.parser.parseBlocks(li, [firstitem]);
      this.parser.state.reset();
    } else if (parent.tag === 'ol' || parent.tag === 'ul') {
      lst = parent;
    } else {
      lst = SubElement(parent, this.TAG);
      if (!this.LAZY_OL && this.STARTSWITH !== '1') lst.set('start', this.STARTSWITH);
    }
    this.parser.state.set('list');
    for (const item of items) {
      if (item.startsWith(' '.repeat(this.tabLength))) {
        this.parser.parseBlocks(lst.child(-1), [item]);
      } else {
        const li = SubElement(lst, 'li');
        this.parser.parseBlocks(li, [item]);
      }
    }
    this.parser.state.reset();
    return undefined;
  }

  getItems(block) {
    const items = [];
    for (const line of block.split('\n')) {
      const m = matchListItem(line, 'any');
      if (m) {
        if (!items.length && this.TAG === 'ol') this.STARTSWITH = leadingInteger(m.marker);
        items.push(m.content);
      } else if (matchIndentedListItem(line, this.tabLength)) {
        if (items.length && items[items.length - 1].startsWith(' '.repeat(this.tabLength))) {
          items[items.length - 1] = items[items.length - 1] + '\n' + line;
        } else {
          items.push(line);
        }
      } else if (items.length) {
        items[items.length - 1] = items[items.length - 1] + '\n' + line;
      } else {
        items.push(line);
      }
    }
    return items;
  }
}

export class UListProcessor extends OListProcessor {
  constructor(parser) {
    super(parser);
    this.TAG = 'ul';
    this.KIND = 'ul';
  }
}

export class HashHeaderProcessor extends BlockProcessor {
  test(parent, block) {
    return searchHashHeader(block) !== null;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    const m = searchHashHeader(block);
    if (m) {
      const before = block.slice(0, m.start);
      const after = block.slice(m.end);
      if (before) this.parser.parseBlocks(parent, [before]);
      const h = SubElement(parent, 'h' + m.level);
      h.text = strip(m.header);
      if (after) blocks.unshift(after);
    }
    return undefined;
  }
}

export class SetextHeaderProcessor extends BlockProcessor {
  test(parent, block) {
    return matchSetextHeader(block) !== null;
  }

  run(parent, blocks) {
    const lines = blocks.shift().split('\n');
    const level = lines[1].startsWith('=') ? 1 : 2;
    const h = SubElement(parent, 'h' + level);
    h.text = strip(lines[0]);
    if (lines.length > 2) blocks.unshift(lines.slice(2).join('\n'));
    return undefined;
  }
}

export class HRProcessor extends BlockProcessor {
  test(parent, block) {
    this.match = searchHR(block);
    return this.match !== null;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    const match = this.match;
    const prelines = rstripChars(block.slice(0, match.start), '\n');
    if (prelines) this.parser.parseBlocks(parent, [prelines]);
    SubElement(parent, 'hr');
    const postlines = lstripChars(block.slice(match.end), '\n');
    if (postlines) blocks.unshift(postlines);
    return undefined;
  }
}

export class ReferenceProcessor extends BlockProcessor {
  test() {
    return true;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    const m = searchReference(block);
    if (m) {
      const id = strip(m.id).toLowerCase();
      const link = rstripChars(lstripChars(m.link, '<'), '>');
      const title = m.title;
      this.parser.md.references.set(id, { href: link, title });
      if (strip(block.slice(m.end))) blocks.unshift(lstripChars(block.slice(m.end), '\n'));
      if (strip(block.slice(0, m.start))) blocks.unshift(rstripChars(block.slice(0, m.start), '\n'));
      return true;
    }
    blocks.unshift(block);
    return false;
  }
}

export class ParagraphProcessor extends BlockProcessor {
  test() {
    return true;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    if (strip(block)) {
      if (this.parser.state.isstate('list')) {
        // Inside a tight list the text joins the item rather than forming a <p>.
        const sibling = this.lastChild(parent);
        if (sibling !== null) {
          sibling.tail = sibling.tail ? sibling.tail + '\n' + block : '\n' + block;
