// Preprocessors run over the document's lines before block parsing.
//   normalize_whitespace 30, html_block 20, reference (block level, not here)
import { STX, ETX, expandTabs } from './util.mjs';
import { replaceAll } from './scan.mjs';

export class Preprocessor {
  constructor(md) {
    this.md = md;
  }

  run(lines) {
    return lines;
  }
}

export class NormalizeWhitespace extends Preprocessor {
  run(lines) {
    let source = lines.join('\n');
    // The placeholder sentinels must not survive from user input.
    source = replaceAll(source, STX, '');
    source = replaceAll(source, ETX, '');
    source = replaceAll(source, '\r\n', '\n');
    source = replaceAll(source, '\r', '\n');
    source += '\n\n';
    source = expandTabs(source, this.md.tabLength);
    source = blankOutSpaceOnlyLines(source);
    return source.split('\n');
  }
}

/**
 * `re.sub(r'(?<=\n) +\n', '\n', source)` — a line made only of spaces becomes
 * empty. The very first line is exempt because the lookbehind needs a newline.
 */
function blankOutSpaceOnlyLines(source) {
  const lines = source.split('\n');
  for (let i = 1; i < lines.length - 1; i++) {
    const line = lines[i];
    if (line.length === 0) continue;
    let allSpaces = true;
    for (let k = 0; k < line.length; k++) {
      if (line[k] !== ' ') { allSpaces = false; break; }
    }
    if (allSpaces) lines[i] = '';
  }
  return lines.join('\n');
}

