// Treeprocessors: inline pattern application (20), prettifying (10), unescaping (0).
import { Element, isElement, parentMap } from './etree.mjs';
import { INLINE_PLACEHOLDER_PREFIX, ETX, STX } from './util.mjs';
import { strip, rstrip } from './scan.mjs';

export class Treeprocessor {
  constructor(md) {
    this.md = md;
  }

  run() {
    return null;
  }
}

/** Reads `\x02<digits>\x03` at `index`; returns the digits and the end offset. */
function readInlinePlaceholder(data, index) {
  if (!data.startsWith(INLINE_PLACEHOLDER_PREFIX, index)) return null;
  let i = index + INLINE_PLACEHOLDER_PREFIX.length;
  const start = i;
  while (i < data.length && data[i] >= '0' && data[i] <= '9') i++;
  if (i === start || data[i] !== ETX) return null;
  return { id: data.slice(start, i), end: i + 1 };
}

/**
 * Applies the registered inline patterns to every text node in the tree.
 *
 * Matched constructs are replaced by placeholders while the text is scanned,
 * then rebuilt into elements — the same two-phase approach the reference
 * implementation uses, which is what makes pattern precedence observable.
 */
export class InlineTreeprocessor extends Treeprocessor {
  constructor(md) {
    super(md);
    this.stashedNodes = new Map();
    this.ancestors = [];
  }

  makePlaceholder() {
    const id = String(this.stashedNodes.size).padStart(4, '0');
    return { placeholder: INLINE_PLACEHOLDER_PREFIX + id + ETX, id };
  }

  stashNode(node) {
    const { placeholder, id } = this.makePlaceholder();
    this.stashedNodes.set(id, node);
    return placeholder;
  }

  buildAncestors(parent, parents) {
    const ancestors = [];
    let current = parent;
    while (current !== null && current !== undefined) {
      ancestors.push(String(current.tag).toLowerCase());
      current = this.parentMap.get(current) || null;
    }
    ancestors.reverse();
    for (const a of ancestors) parents.push(a);
  }

  /** Runs one pattern over `data`, returning the rewritten text. */
  applyPattern(pattern, data, patternIndex, startIndex) {
    for (const exclude of pattern.ANCESTOR_EXCLUDES || []) {
      if (this.ancestors.indexOf(exclude.toLowerCase()) !== -1) return { data, matched: false, startIndex: 0 };
    }
    let match = null;
    let node = null;
    let start = null;
    let end = null;
    let cursor = startIndex;
    for (;;) {
      const found = pattern.find(data, cursor);
      if (!found) { match = null; break; }
      const result = pattern.handleMatch(found, data);
      node = result.node;
      start = result.start;
      end = result.end;
      if (start === null || end === null || start === undefined || end === undefined) {
        // The pattern declined this match; resume past it.
        cursor = startIndex + found.end;
        startIndex = cursor;
        match = null;
        if (found.end <= found.start) cursor = found.start + 1;
        continue;
      }
      match = found;
      break;
    }
    if (!match) return { data, matched: false, startIndex: 0 };
    if (node === null || node === undefined) return { data, matched: true, startIndex: end };

    if (typeof node !== 'string') {
      if (!node.atomicText) {
        // The new element's own text still needs the *later* patterns applied.
        const targets = [node, ...node.children];
        for (const child of targets) {
          if (!isElement(child)) continue;
          if (child.text) child.text = this.handleInline(child.text, patternIndex + 1);
          if (child.tail) child.tail = this.handleInline(child.tail, patternIndex);
        }
      }
    }
    const placeholder = typeof node === 'string' ? node : this.stashNode(node);
    return {
      data: data.slice(0, start) + placeholder + data.slice(end),
      matched: true,
      startIndex: 0,
    };
  }

  handleInline(data, patternIndex = 0) {
    let text = data;
    let index = patternIndex;
    let startIndex = 0;
    const patterns = this.md.inlinePatterns.values();
    while (index < patterns.length) {
      const res = this.applyPattern(patterns[index], text, index, startIndex);
      text = res.data;
      startIndex = res.startIndex;
      if (!res.matched) index += 1;
    }
    return text;
  }

  /**
   * Walks `data`, converting placeholders back into elements. Text between
   * placeholders is attached to the right node's text or tail.
   */
  processPlaceholders(data, parent, isText = true, atomic = false) {
    const result = [];
    const linkText = (text) => {
      if (!text) return;
      if (result.length) {
        const last = result[result.length - 1][0];
        last.tail = last.tail ? last.tail + text : text;
      } else if (!isText) {
        parent.tail = parent.tail ? parent.tail + text : text;
      } else {
        parent.text = parent.text ? parent.text + text : text;
      }
    };

    let startIndex = 0;
    let working = data;
    while (working) {
      const index = working.indexOf(STX, startIndex);
      if (index !== -1) {
        const ph = readInlinePlaceholder(working, index);
        const id = ph ? ph.id : null;
        const phEnd = ph ? ph.end : index + 1;
        if (id !== null && this.stashedNodes.has(id)) {
          const text = working.slice(startIndex, index);
          if (text) linkText(text);
          const node = this.stashedNodes.get(id);
