      text = res.data;
      startIndex = res.startIndex;
      if (!res.matched) index += 1;
    }
    return text;
  }

  /**
   * Walks `data`, converting placeholders back into elements. Text between
   * placeholders is attached to the right node's text or tail.
   */
  processPlaceholders(data, parent, isText = true, atomic = false) {
    const result = [];
    const linkText = (text) => {
      if (!text) return;
      if (result.length) {
        const last = result[result.length - 1][0];
        last.tail = last.tail ? last.tail + text : text;
      } else if (!isText) {
        parent.tail = parent.tail ? parent.tail + text : text;
      } else {
        parent.text = parent.text ? parent.text + text : text;
      }
    };

    let startIndex = 0;
    let working = data;
    while (working) {
      const index = working.indexOf(STX, startIndex);
      if (index !== -1) {
        const ph = readInlinePlaceholder(working, index);
        const id = ph ? ph.id : null;
        const phEnd = ph ? ph.end : index + 1;
        if (id !== null && this.stashedNodes.has(id)) {
          const text = working.slice(startIndex, index);
          if (text) linkText(text);
          const node = this.stashedNodes.get(id);
          if (typeof node !== 'string') {
            for (const child of [node, ...node.children]) {
              if (!isElement(child)) continue;
              if (child.tail && strip(child.tail)) this.processElementText(node, child, false);
              if (child.text && strip(child.text)) this.processElementText(child, child, true);
            }
            startIndex = phEnd;
            result.push([node, this.ancestors.slice()]);
          } else {
            linkText(node);
            startIndex = phEnd;
          }
        } else {
          // Not one of ours: keep the sentinel as literal text.
          const end = index + 1;
          linkText(working.slice(startIndex, end));
          startIndex = end;
        }
      } else {
        linkText(working.slice(startIndex));
        working = '';
      }
    }
    void atomic;
    return result;
  }

  processElementText(node, subnode, isText = true) {
    let text;
    if (isText) {
      text = subnode.text;
      subnode.text = null;
    } else {
      text = subnode.tail;
      subnode.tail = null;
    }
    const childResult = this.processPlaceholders(text, subnode, isText);
    const pos = (!isText && node !== subnode) ? node.findIndex(subnode) + 1 : 0;
    childResult.reverse();
    for (const item of childResult) node.insert(pos, item[0]);
  }

  run(tree, ancestors = null) {
    this.stashedNodes = new Map();
    this.parentMap = parentMap(tree);
    const stack = [[tree, ancestors === null ? [] : ancestors.slice()]];

    while (stack.length) {
      const [currElement, parents] = stack.pop();
      this.ancestors = parents;
      this.buildAncestors(currElement, this.ancestors);

      const insertQueue = [];
      // Indexed walk: nodes spliced in by tail handling are visited in turn,
      // exactly as a Python list iterator would.
      for (let ci = 0; ci < currElement.children.length; ci++) {
        const child = currElement.children[ci];
        if (!isElement(child)) continue;
        if (child.text && !child.atomicText) {
          this.ancestors.push(String(child.tag).toLowerCase());
          const text = child.text;
          child.text = null;
          const lst = this.processPlaceholders(this.handleInline(text), child, true);
          for (const item of lst) this.parentMap.set(item[0], child);
          for (const item of lst) stack.push(item);
          insertQueue.push([child, lst]);
          this.ancestors.pop();
        }
        if (child.tail) {
          const tail = this.handleInline(child.tail);
          const dumby = new Element('d');
          child.tail = null;
          const tailResult = this.processPlaceholders(tail, dumby, false);
          if (dumby.tail) child.tail = dumby.tail;
          for (const item of tailResult) this.parentMap.set(item[0], this.parentMap.get(child));
          for (const item of tailResult) stack.push(item);
          if (dumby.length) {
            const pos = currElement.findIndex(child) + 1;
            currElement.children.splice(pos, 0, ...dumby.children);
          }
        }
        if (child.length) {
          this.parentMap.set(child, currElement);
          stack.push([child, this.ancestors.slice()]);
        }
      }

      for (const [element, lst] of insertQueue) {
        for (let i = 0; i < lst.length; i++) element.insert(i, lst[i][0]);
      }
    }
    return tree;
  }
}

export class PrettifyTreeprocessor extends Treeprocessor {
  prettifyETree(elem) {
    const i = '\n';
    if (this.md.isBlockLevel(elem.tag) && elem.tag !== 'code' && elem.tag !== 'pre') {
      if ((!elem.text || !strip(elem.text)) && elem.length && this.md.isBlockLevel(elem.child(0).tag)) {
        elem.text = i;
      }
      for (const e of elem.children) {
        if (isElement(e) && this.md.isBlockLevel(e.tag)) this.prettifyETree(e);
      }
      if (!elem.tail || !strip(elem.tail)) elem.tail = i;
    }
  }

  run(root) {
    this.prettifyETree(root);
    for (const e of root.iter('br')) {
      if (!e.tail || !strip(e.tail)) e.tail = '\n';
    }
    for (const pre of root.iter('pre')) {
      if (pre.length && pre.child(0).tag === 'code') {
        const code = pre.child(0);
        if (!code.length && code.text !== null) {
          code.text = rstrip(code.text) + '\n';
          code.atomicText = true;
        }
      }
    }
    return null;
  }
}

/** Restores characters that were stashed as `\x02<codepoint>\x03` by escaping. */
export class UnescapeTreeprocessor extends Treeprocessor {
  unescape(text) {
    if (text.indexOf(STX) === -1) return text;
    let out = '';
    let i = 0;
    while (i < text.length) {
      if (text[i] === STX) {
        let j = i + 1;
        while (j < text.length && text[j] >= '0' && text[j] <= '9') j++;
        if (j > i + 1 && text[j] === ETX) {
          out += String.fromCodePoint(Number(text.slice(i + 1, j)));
          i = j + 1;
          continue;
        }
      }
      out += text[i];
      i += 1;
    }
    return out;
  }

  run(root) {
    for (const elem of root.iter()) {
      if (elem.text && elem.tag !== 'code') elem.text = this.unescape(elem.text);
      for (const [key, value] of elem.items()) elem.set(key, this.unescape(String(value)));
      if (elem.tail) elem.tail = this.unescape(elem.tail);
    }
    return null;
  }
}

export function buildTreeprocessors(md) {
  const registry = md.treeprocessors;
  registry.register(new InlineTreeprocessor(md), 'inline', 20);
  registry.register(new PrettifyTreeprocessor(md), 'prettify', 10);
  registry.register(new UnescapeTreeprocessor(md), 'unescape', 0);
  return registry;
}

