// Shared base class for inline pattern processors.
//
// Each processor exposes:
//   find(data, from)      -> {start, end, groups} | null   (next match at or after `from`)
//   handleMatch(m, data)  -> {node, start, end}            (node may be an Element,
//                                                           a string, or null to decline)
import { INLINE_PLACEHOLDER_PREFIX, ETX, STX } from '../util.mjs';
import { toHtmlString } from '../serializer.mjs';

export class InlineProcessor {
  constructor(md) {
    this.md = md;
    this.ANCESTOR_EXCLUDES = [];
  }

  find() {
    return null;
  }

  handleMatch() {
    return { node: null, start: null, end: null };
  }

  /** Replaces inline placeholders with the serialized form of their node. */
  unescape(text) {
    if (text.indexOf(STX) === -1) return text;
    const stash = this.md.treeprocessors.get('inline').stashedNodes;
    let out = '';
    let i = 0;
    while (i < text.length) {
      if (text.startsWith(INLINE_PLACEHOLDER_PREFIX, i)) {
        let j = i + INLINE_PLACEHOLDER_PREFIX.length;
        const digitStart = j;
        while (j < text.length && text[j] >= '0' && text[j] <= '9') j++;
        if (j > digitStart && text[j] === ETX) {
          const id = text.slice(digitStart, j);
          if (stash.has(id)) {
            const value = stash.get(id);
            out += typeof value === 'string' ? value : toHtmlString(value, this.md.outputFormat);
            i = j + 1;
            continue;
          }
        }
      }
      out += text[i];
      i += 1;
    }
    return out;
  }

  /** Puts back characters that the escape processor stashed. */
  backslashUnescape(text) {
    return this.md.treeprocessors.get('unescape').unescape(text);
  }
}

/** Finds the next occurrence of a single literal character. */
export function findChar(data, from, ch) {
  const at = data.indexOf(ch, from);
  return at === -1 ? null : at;
}

