// The non-emphasis, non-link inline patterns:
//   backtick 190, escape 180, autolink 120, automail 110, linebreak 100,
//   html 90, entity 80, not_strong 70
import { Element } from '../etree.mjs';
import { STX, ETX, AMP_SUBSTITUTE, codeEscape } from '../util.mjs';
import { isWordAt, isSpaceCodePoint, strip, runLength, isAsciiAlpha, isDigit } from '../scan.mjs';
import { InlineProcessor } from './base.mjs';
import { codepointToName } from '../entities.mjs';

const ESCAPED_BSLASH = STX + '92' + ETX;

/**
 * `(?:(?<!\\)((?:\\{2})+)(?=`+)|(?<!\\)(`+)(.+?)(?<!`)\2(?!`))`
 *
 * Alternative one protects an even run of backslashes before a backtick;
 * alternative two is the code span itself.
 */
export class BacktickInlineProcessor extends InlineProcessor {
  find(data, from) {
    for (let p = Math.max(0, from); p < data.length; p++) {
      if (p > 0 && data[p - 1] === '\\') continue;
      if (data[p] === '\\') {
        const run = runLength(data, p, '\\');
        if (run % 2 === 0 && data[p + run] === '`') {
          return { start: p, end: p + run, groups: [data.slice(p, p + run), null, null] };
        }
        continue;
      }
      if (data[p] !== '`') continue;
      const full = runLength(data, p, '`');
      // The delimiter run is greedy, so longer runs are tried first.
      for (let runLen = full; runLen >= 1; runLen--) {
        const contentStart = p + runLen;
        for (let len = 1; contentStart + len + runLen <= data.length; len++) {
          const q = contentStart + len;
          if (data[q - 1] === '`') continue; // `(?<!`)` before the closing run
          let ok = true;
          for (let k = 0; k < runLen; k++) {
            if (data[q + k] !== '`') { ok = false; break; }
          }
          if (!ok) continue;
          if (data[q + runLen] === '`') continue; // `(?!`)` after it
          return {
            start: p,
            end: q + runLen,
            groups: [null, data.slice(p, p + runLen), data.slice(contentStart, q)],
          };
        }
      }
    }
    return null;
  }

  handleMatch(m) {
    if (m.groups[2] !== null && m.groups[2] !== undefined) {
      const el = new Element('code');
      el.text = codeEscape(strip(m.groups[2]));
      el.atomicText = true;
      return { node: el, start: m.start, end: m.end };
    }
    return {
      node: m.groups[0].split('\\\\').join(ESCAPED_BSLASH),
      start: m.start,
      end: m.end,
    };
  }
}

/** `\\(.)` with DOTALL — stashes the escaped character as `\x02<code>\x03`. */
export class EscapeInlineProcessor extends InlineProcessor {
  find(data, from) {
    for (let p = Math.max(0, from); p < data.length - 1; p++) {
      if (data[p] === '\\') return { start: p, end: p + 2, groups: [data[p + 1]] };
    }
    return null;
  }

  handleMatch(m) {
    const char = m.groups[0];
    if (this.md.ESCAPED_CHARS.indexOf(char) !== -1) {
      return { node: STX + char.codePointAt(0) + ETX, start: m.start, end: m.end };
    }
    return { node: null, start: m.start, end: m.end };
  }
}

/** `((^|(?<=\s))(\*{1,3}|_{1,3})(?=\s|$))` — a lone run of markers stays literal. */
export class SimpleTextInlineProcessor extends InlineProcessor {
  find(data, from) {
    for (let p = Math.max(0, from); p < data.length; p++) {
      const ch = data[p];
      if (ch !== '*' && ch !== '_') continue;
      if (p !== 0 && !isSpaceCodePoint(data.charCodeAt(p - 1))) continue;
      const run = Math.min(runLength(data, p, ch), 3);
      for (let n = run; n >= 1; n--) {
        const after = p + n;
        if (after === data.length
          || (after === data.length - 1 && data[after] === '\n')
          || isSpaceCodePoint(data.charCodeAt(after))) {
          return { start: p, end: after, groups: [data.slice(p, after)] };
        }
      }
    }
    return null;
  }

  handleMatch(m) {
    return { node: m.groups[0], start: m.start, end: m.end };
  }
}

/** `  \n` — two spaces at end of line become a `<br>`. */
export class SubstituteTagInlineProcessor extends InlineProcessor {
  constructor(md, tag) {
    super(md);
    this.tag = tag;
  }

  find(data, from) {
    const at = data.indexOf('  \n', Math.max(0, from));
    return at === -1 ? null : { start: at, end: at + 3, groups: [] };
  }

  handleMatch(m) {
    return { node: new Element(this.tag), start: m.start, end: m.end };
  }
}

/** `<((?:[Ff]|[Hh][Tt])[Tt][Pp][Ss]?://[^<>]*)>` */
export class AutolinkInlineProcessor extends InlineProcessor {
  find(data, from) {
    for (let p = Math.max(0, from); p < data.length; p++) {
      if (data[p] !== '<') continue;
      let i = p + 1;
      const c0 = data[i];
      if (c0 === 'f' || c0 === 'F') i += 1;
      else if ((c0 === 'h' || c0 === 'H') && (data[i + 1] === 't' || data[i + 1] === 'T')) i += 2;
      else continue;
      if (!(data[i] === 't' || data[i] === 'T')) continue;
      i += 1;
      if (!(data[i] === 'p' || data[i] === 'P')) continue;
      i += 1;
      if (data[i] === 's' || data[i] === 'S') i += 1;
      if (data.slice(i, i + 3) !== '://') continue;
      i += 3;
      let j = i;
      while (j < data.length && data[j] !== '<' && data[j] !== '>') j++;
      if (data[j] !== '>') continue;
      return { start: p, end: j + 1, groups: [data.slice(p + 1, j)] };
    }
    return null;
  }

  handleMatch(m) {
    const el = new Element('a');
    el.set('href', this.unescape(m.groups[0]));
    el.text = m.groups[0];
    el.atomicText = true;
    return { node: el, start: m.start, end: m.end };
  }
}

/** `<([^<> !]+@[^@<> ]+)>` — the address is emitted as character references. */
export class AutomailInlineProcessor extends InlineProcessor {
  find(data, from) {
    for (let p = Math.max(0, from); p < data.length; p++) {
      if (data[p] !== '<') continue;
      // `[^<> !]+` runs to the first excluded character; the last `@` inside wins.
      let end = p + 1;
      while (end < data.length && '<> !'.indexOf(data[end]) === -1) end++;
      for (let at = end - 1; at > p + 1; at--) {
        if (data[at] !== '@') continue;
        let d = at + 1;
        while (d < data.length && '@<> '.indexOf(data[d]) === -1) d++;
        if (d === at + 1) continue;
        if (data[d] !== '>') continue;
        return { start: p, end: d + 1, groups: [data.slice(p + 1, d)] };
      }
    }
    return null;
  }

  handleMatch(m) {
    const el = new Element('a');
    let email = this.unescape(m.groups[0]);
    if (email.startsWith('mailto:')) email = email.slice('mailto:'.length);
    const encodeChar = (cp) => {
      const name = codepointToName(cp);
      return name ? AMP_SUBSTITUTE + name + ';' : AMP_SUBSTITUTE + '#' + cp + ';';
    };
    let text = '';
    for (const letter of email) text += encodeChar(letter.codePointAt(0));
    el.text = text;
    el.atomicText = true;
    let mailto = '';
    for (const letter of 'mailto:' + email) mailto += AMP_SUBSTITUTE + '#' + letter.codePointAt(0) + ';';
    el.set('href', mailto);
    return { node: el, start: m.start, end: m.end };
  }
}

/** Stashes raw inline HTML (or an entity) so later stages leave it alone. */
export class HtmlInlineProcessor extends InlineProcessor {
  constructor(md, kind) {
    super(md);
    this.kind = kind; // 'html' or 'entity'
  }

  find(data, from) {
    return this.kind === 'html' ? findInlineHtml(data, from) : findEntity(data, from);
  }

  handleMatch(m) {
    const rawhtml = this.backslashUnescape(this.unescape(m.groups[0]));
    return { node: this.md.htmlStash.store(rawhtml), start: m.start, end: m.end };
  }
}

/** `(<(\/?[a-zA-Z][^<>]*|!--(?:(?!<!--|-->).)*--)>)` */
function findInlineHtml(data, from) {
  for (let p = Math.max(0, from); p < data.length; p++) {
    if (data[p] !== '<') continue;
    let i = p + 1;
    if (data.startsWith('!--', i)) {
      // Comment body may contain neither `<!--` nor `-->`.
      let j = i + 3;
      for (;;) {
        if (j + 1 >= data.length) { j = -1; break; }
        if (data.startsWith('-->', j)) break;
        if (data.startsWith('<!--', j)) { j = -1; break; }
        j += 1;
      }
      if (j === -1) continue;
      return { start: p, end: j + 3, groups: [data.slice(p, j + 3)] };
    }
    if (data[i] === '/') i += 1;
    if (!isAsciiAlpha(data[i] || '')) continue;
    i += 1;
    while (i < data.length && data[i] !== '<' && data[i] !== '>') i++;
    if (data[i] !== '>') continue;
    return { start: p, end: i + 1, groups: [data.slice(p, i + 1)] };
  }
  return null;
}

/** `(&(?:\#[0-9]+|\#x[0-9a-fA-F]+|[a-zA-Z0-9]+);)` */
function findEntity(data, from) {
  for (let p = Math.max(0, from); p < data.length; p++) {
    if (data[p] !== '&') continue;
    let i = p + 1;
    if (data[i] === '#') {
      i += 1;
      if (data[i] === 'x' || data[i] === 'X') {
        // Only lowercase `x` is accepted by the pattern.
        if (data[i] !== 'x') continue;
        i += 1;
        const s = i;
        while (i < data.length && isHex(data[i])) i++;
        if (i === s) continue;
      } else {
        const s = i;
        while (i < data.length && isDigit(data[i])) i++;
        if (i === s) continue;
      }
    } else {
      const s = i;
      while (i < data.length && (isAsciiAlpha(data[i]) || isDigit(data[i]))) i++;
      if (i === s) continue;
    }
    if (data[i] !== ';') continue;
    return { start: p, end: i + 1, groups: [data.slice(p, i + 1)] };
  }
  return null;
}

function isHex(ch) {
  return isDigit(ch) || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
}

export { isWordAt };

