// Emphasis and strong emphasis.
//
// Both processors work the same way: find the next marker character, then try a
// fixed, ordered list of shapes anchored at that position. The first shape that
// fits wins, and its inner text is re-scanned with only the *later* shapes,
// which is what produces the nesting behaviour.
import { Element } from '../etree.mjs';
import { isWordAt } from '../scan.mjs';
import { InlineProcessor } from './base.mjs';

function notWordAt(data, i) {
  return !isWordAt(data, i);
}

/** `(X)\1{2}(.+?)\1(.*?)\1{2}` */
function matchEmStrong(data, pos, X) {
  if (data[pos] !== X || data[pos + 1] !== X || data[pos + 2] !== X) return null;
  const body = pos + 3;
  for (let len2 = 1; body + len2 < data.length; len2++) {
    const q = body + len2;
    if (data[q] !== X) continue;
    for (let len3 = 0; q + 1 + len3 + 1 < data.length; len3++) {
      const r = q + 1 + len3;
      if (data[r] === X && data[r + 1] === X) {
        return { end: r + 2, g2: data.slice(body, q), g3: data.slice(q + 1, r) };
      }
    }
  }
  return null;
}

/** `(X)\1{2}(.+?)\1{2}(.*?)\1` */
function matchStrongEm(data, pos, X) {
  if (data[pos] !== X || data[pos + 1] !== X || data[pos + 2] !== X) return null;
  const body = pos + 3;
  for (let len2 = 1; body + len2 + 1 < data.length; len2++) {
    const q = body + len2;
    if (data[q] !== X || data[q + 1] !== X) continue;
    for (let len3 = 0; q + 2 + len3 < data.length; len3++) {
      const r = q + 2 + len3;
      if (data[r] === X) {
        return { end: r + 1, g2: data.slice(body, q), g3: data.slice(q + 2, r) };
      }
    }
  }
  return null;
}

/** `(X)\1(?!\1)([^X]+?)\1(?!\1)(.+?)\1{3}` */
function matchStrongEm3(data, pos, X) {
  if (data[pos] !== X || data[pos + 1] !== X) return null;
  if (data[pos + 2] === X || data[pos + 2] === undefined) return null;
  const body = pos + 2;
  for (let len2 = 1; body + len2 < data.length; len2++) {
    const q = body + len2;
    if (data[q - 1] === X) break; // `[^X]+?` cannot contain the marker
    if (data[q] !== X) continue;
    if (data[q + 1] === X) continue;
    for (let len3 = 1; q + 1 + len3 + 2 < data.length + 1; len3++) {
      const r = q + 1 + len3;
      if (data[r] === X && data[r + 1] === X && data[r + 2] === X) {
        return { end: r + 3, g2: data.slice(body, q), g3: data.slice(q + 1, r) };
      }
    }
  }
  return null;
}

/** `(X{2})(.+?)\1` */
function matchStrong(data, pos, X) {
  if (data[pos] !== X || data[pos + 1] !== X) return null;
  const body = pos + 2;
  for (let len2 = 1; body + len2 + 1 < data.length; len2++) {
    const q = body + len2;
    if (data[q] === X && data[q + 1] === X) return { end: q + 2, g2: data.slice(body, q), g3: null };
  }
  return null;
}

/** `(X)([^X]+)\1` — greedy body, so the next marker closes it. */
function matchEm(data, pos, X) {
  if (data[pos] !== X) return null;
  let j = pos + 1;
  while (j < data.length && data[j] !== X) j++;
  if (j === pos + 1 || j >= data.length) return null;
  return { end: j + 1, g2: data.slice(pos + 1, j), g3: null };
}

/** `(?<!\w)(_{2})(?!_)(.+?)(?<!_)\1(?!\w)` */
function matchSmartStrong(data, pos) {
  if (!notWordAt(data, pos - 1)) return null;
  if (data[pos] !== '_' || data[pos + 1] !== '_') return null;
  if (data[pos + 2] === '_') return null;
  const body = pos + 2;
  for (let len2 = 1; body + len2 + 1 < data.length; len2++) {
    const q = body + len2;
    if (data[q - 1] === '_') continue;
    if (data[q] !== '_' || data[q + 1] !== '_') continue;
    if (!notWordAt(data, q + 2)) continue;
    return { end: q + 2, g2: data.slice(body, q), g3: null };
  }
  return null;
}

/** `(?<!\w)(_)(?!_)(.+?)(?<!_)\1(?!\w)` */
function matchSmartEm(data, pos) {
  if (!notWordAt(data, pos - 1)) return null;
  if (data[pos] !== '_') return null;
  if (data[pos + 1] === '_') return null;
  const body = pos + 1;
  for (let len2 = 1; body + len2 < data.length; len2++) {
    const q = body + len2;
    if (data[q - 1] === '_') continue;
    if (data[q] !== '_') continue;
    if (!notWordAt(data, q + 1)) continue;
    return { end: q + 1, g2: data.slice(body, q), g3: null };
  }
  return null;
}

/** `(?<!\w)(_)\1(?!\1)([^_]+?)\1(?!\1)(.+?)\1{3}(?!\w)` */
function matchSmartStrongEm(data, pos) {
  if (!notWordAt(data, pos - 1)) return null;
  const m = matchStrongEm3(data, pos, '_');
  if (!m) return null;
  if (!notWordAt(data, m.end)) return null;
  return m;
}

