  { match: (d, p) => matchEmStrong(d, p, '*'), builder: 'double', tags: 'strong,em' },
  { match: (d, p) => matchStrongEm(d, p, '*'), builder: 'double', tags: 'em,strong' },
  { match: (d, p) => matchStrongEm3(d, p, '*'), builder: 'double2', tags: 'strong,em' },
  { match: (d, p) => matchStrong(d, p, '*'), builder: 'single', tags: 'strong' },
  { match: (d, p) => matchEm(d, p, '*'), builder: 'single', tags: 'em' },
];

const UNDERSCORE_PATTERNS = [
  { match: (d, p) => matchEmStrong(d, p, '_'), builder: 'double', tags: 'strong,em' },
  { match: (d, p) => matchStrongEm(d, p, '_'), builder: 'double', tags: 'em,strong' },
  { match: matchSmartStrongEm, builder: 'double2', tags: 'strong,em' },
  { match: matchSmartStrong, builder: 'single', tags: 'strong' },
  { match: matchSmartEm, builder: 'single', tags: 'em' },
];

class EmStrongProcessor extends InlineProcessor {
  constructor(md, marker, patterns) {
    super(md);
    this.marker = marker;
    this.PATTERNS = patterns;
  }

  find(data, from) {
    const at = data.indexOf(this.marker, Math.max(0, from));
    return at === -1 ? null : { start: at, end: at + 1, groups: [] };
  }

  buildElement(m, builder, tags, index) {
    if (builder === 'double2') return this.buildDouble2(m, tags, index);
    if (builder === 'double') return this.buildDouble(m, tags, index);
    return this.buildSingle(m, tags, index);
  }

  buildSingle(m, tag, idx) {
    const el = new Element(tag);
    this.parseSubPatterns(m.g2, el, null, idx);
    return el;
  }

  buildDouble(m, tags, idx) {
    const [tag1, tag2] = tags.split(',');
    const el1 = new Element(tag1);
    const el2 = new Element(tag2);
    this.parseSubPatterns(m.g2, el2, null, idx);
    el1.append(el2);
    this.parseSubPatterns(m.g3, el1, el2, idx);
    return el1;
  }

  buildDouble2(m, tags, idx) {
    const [tag1, tag2] = tags.split(',');
    const el1 = new Element(tag1);
    const el2 = new Element(tag2);
    this.parseSubPatterns(m.g2, el1, null, idx);
    this.parseSubPatterns(m.g3, el2, null, idx);
    el1.append(el2);
    return el1;
  }

  /** Re-scans inner text with the shapes that come after the one already used. */
  parseSubPatterns(data, parent, last, idx) {
    if (data === null || data === undefined) return;
    let offset = 0;
    let pos = 0;
    const length = data.length;
    const addText = (text) => {
      if (!text) return;
      if (last !== null) last.tail = text;
      else if (parent.text === null) parent.text = text;
      else parent.text += text;
    };
    while (pos < length) {
      if (data[pos] === this.marker) {
        let matched = false;
        for (let index = 0; index < this.PATTERNS.length; index++) {
          if (index <= idx) continue;
          const m = this.PATTERNS[index].match(data, pos);
          if (m) {
            addText(data.slice(offset, pos));
            const el = this.buildElement(m, this.PATTERNS[index].builder, this.PATTERNS[index].tags, index);
            parent.append(el);
            last = el;
            offset = m.end;
            pos = m.end;
            matched = true;
          }
        }
        if (!matched) pos += 1;
      } else {
        pos += 1;
      }
    }
    addText(data.slice(offset));
  }

  handleMatch(m, data) {
    for (let index = 0; index < this.PATTERNS.length; index++) {
      const m1 = this.PATTERNS[index].match(data, m.start);
      if (m1) {
        const el = this.buildElement(m1, this.PATTERNS[index].builder, this.PATTERNS[index].tags, index);
        return { node: el, start: m.start, end: m1.end };
      }
    }
    return { node: null, start: null, end: null };
  }
}

export class AsteriskProcessor extends EmStrongProcessor {
  constructor(md) {
    super(md, '*', ASTERISK_PATTERNS);
  }
}

export class UnderscoreProcessor extends EmStrongProcessor {
  constructor(md) {
    super(md, '_', UNDERSCORE_PATTERNS);
  }
}

