    return at === -1 ? null : { start: at, end: at + 1, groups: [] };
  }

  buildElement(m, builder, tags, index) {
    if (builder === 'double2') return this.buildDouble2(m, tags, index);
    if (builder === 'double') return this.buildDouble(m, tags, index);
    return this.buildSingle(m, tags, index);
  }

  buildSingle(m, tag, idx) {
    const el = new Element(tag);
    this.parseSubPatterns(m.g2, el, null, idx);
    return el;
  }

  buildDouble(m, tags, idx) {
    const [tag1, tag2] = tags.split(',');
    const el1 = new Element(tag1);
    const el2 = new Element(tag2);
    this.parseSubPatterns(m.g2, el2, null, idx);
    el1.append(el2);
    this.parseSubPatterns(m.g3, el1, el2, idx);
    return el1;
  }

  buildDouble2(m, tags, idx) {
    const [tag1, tag2] = tags.split(',');
    const el1 = new Element(tag1);
    const el2 = new Element(tag2);
    this.parseSubPatterns(m.g2, el1, null, idx);
    this.parseSubPatterns(m.g3, el2, null, idx);
    el1.append(el2);
    return el1;
  }

  /** Re-scans inner text with the shapes that come after the one already used. */
  parseSubPatterns(data, parent, last, idx) {
    if (data === null || data === undefined) return;
    let offset = 0;
    let pos = 0;
    const length = data.length;
    const addText = (text) => {
      if (!text) return;
      if (last !== null) last.tail = text;
      else if (parent.text === null) parent.text = text;
